Следующая реализация Discord.js бота с одной командой бан:

1. Создайте новый файл, названный `index.js`, и импортируйте необходимые библиотеки:

```javascript
const { Client, GatewayIntentBits } = require('discord.js');

const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
  ],
});

module.exports = client;
```

2. Создайте новый файл, названный `config.json`, и добавьте в него следующие настройки:

```json
{
  "token": "ВАШ_ТОКЕН_ДИСКОРДА",
  "guildId": "ИД_СЕРВЕРА_ДИСКОРДА",
  "modRoleId": "Роль_Модераторов_ID"
}
```

3. Импортируйте файлы `index.js` и `config.json` в новый файл, названный `main.js`, и добавьте следующий код:

```javascript
const { Client, Events } = require('discord.js');
const { token, guildId, modRoleId } = require('./config.json');

const client = new Client();

client.on(Events.InteractionCreate, async (interaction) => {
  if (!interaction.isChatInputCommand()) return;

  if (interaction.commandName === 'ban') {
    if (!interaction.memberPermissions?.has('BAN_MEMBERS')) {
      return interaction.reply({ content: 'У вас нет разрешений для выполнения этой команды', ephemeral: true });
    }

    const targetMember = interaction.guild.members.cache.get(interaction.options.getUser('user').id);

    if (!targetMember) {
      return interaction.reply({ content: 'Невозможно найти участника', ephemeral: true });
    }

    if (targetMember.id === interaction.user.id) {
      return interaction.reply({ content: 'Нельзя банить себя', ephemeral: true });
    }

    if (targetMember.permissionsIn(interaction.channel).has('ADMINISTRATOR')) {
      return interaction.reply({ content: 'Невозможно банить администратора', ephemeral: true });
    }

    if (targetMember.roles.cache.has(modRoleId)) {
      return interaction.reply({ content: 'Невозможно банить модератора', ephemeral: true });
    }

    try {
      await targetMember.ban({ days: 7, reason: `Команда бан от ${interaction.user.tag}` });

      interaction.reply({ content: `${targetMember.user.tag} был успешно забанен`, ephemeral: false });
    } catch (error) {
      console.error(error);
      return interaction.reply({ content: 'Невозможно выполнить команду', ephemeral: true });
    }
  }
});

client.login(token);
```

4. Скачайте последнюю версию `node_modules` с помощью npm, запустите ваш сервер:

```bash
npm install --save discord.js@latest
```

5. Включите режим разработки в Discord Developer Portal, создайте новый приложение, выберите "Регистрация вебхуков" и скопируйте URL, чтобы получить Client ID.

6. Настройте бота в Discord Developer Portal:

- Войдите в Discord Developer Portal и выберите ваше приложение.
- Перейдите в настройки > Бот.
- Введите Client ID в поле "Клиентский ID".
- Включите "Сохранить изменения".

7. Установите новый webhook в Discord:

- Войдите в Discord и откройте канал, в котором хотите использовать бота.
- Нажмите на кнопку "Настройки канала".
- Перейдите в "Webhooks".
- Нажмите на кнопку "Новый вебхук".
- Введите имя вебхука (например, "Ban Bot").
- Введите URL вебхука в `config.json` в файле `main.js` (откройте файл, замените `YOUR_WEBHOOK_URL` на URL, скопированный из Discord Developer Portal):
   ```json
   {
     "token": "ВАШ_ТОКЕН_ДИСКОРДА",
     "guildId": "ИД_СЕРВЕРА_ДИСКОРДА",
     "modRoleId": "Роль_Модераторов_ID",
     "webhookUrl": "ВАШ_ВЕБХУК_URL"
   }
   ```
- Нажмите на кнопку "Сохранить вебхук".

8. Запустите ваш сервер:

```bash
node main.js
```

9. Создайте новый слэш-команду в Discord:

- Войдите в Discord и откройте канал, в котором хотите использовать бота.
- Нажмите на кнопку "Настройки канала".
