            size_t pos = 0;
            string token;
            while ((pos = line.find(" ")) != string::npos) {
                token = line.substr(pos, pos + 1);
                words.push_back(token);
                line.erase(pos, pos + 1);
            }
            words.push_back(line);

            for (auto& w : words) {
                if (w == word) {
                    count++;
                }
            }
        }
        file.close();
    } else {
        cout << "Не удалось открыть файл!" << endl;
        return 1;
